		\sqrt{r(s)}&=\frac{p(s)}{2}\sqrt{1+ \frac{2p'(s)}{p(s)^2} - \frac{4\lambda}{\eps(s)p(s)^2}}
		\\&= \frac{p(s)}{2}\left(1 + \frac{p'(s)}{p(s)^2} - \frac{2\lambda}{\eps(s)p(s)^2} - \frac{1}{8}\left(\frac{2p'(s)}{p(s)^2} - \frac{4\lambda}{\eps(s)p(s)^2}\right)^2 + o(\eps(s)^2) \right)
		\\ & = \frac{p(s)}{2} +\frac{ p'(s)}{2p(s)} - \frac{\lambda}{\eps(s)p(s)} - \frac{1}{16}\left(\frac{2p'(s)}{p(s)^{3/2}} - \frac{4\lambda}{\eps(s)p(s)^{3/2}}\right)^2 + o(\eps(s))
		\\  = \frac{p(s)}{2} &+ \frac{p'(s)\eps(s)}{2(\alpha(s)+\beta\lambda)} - \frac{\lambda}{\alpha(s)+\beta\lambda} - \frac{1}{16}\left(\frac{2p'(s)}{p(s)^{3/2}} - \frac{4\lambda\sqrt{\eps(s)}}{(\alpha(s)+\beta\lambda)^{3/2}}\right)^2 + o(\eps(s))
		\\  = \frac{p(s)}{2} &+ \frac{\alpha'(s)/2-\lambda}{\alpha(s)+\beta\lambda} -\frac{\eps'(s)}{2\eps(s)}  - \frac{1}{16}\left(\frac{2p'(s)}{p(s)^{3/2}} - \frac{4\lambda\sqrt{\eps(s)}}{(\alpha(s)+\beta\lambda)^{3/2}}\right)^2 + o(\eps(s))
	\end{split}
\end{align}

To ease the readability, we denote $h(t)=\left(\frac{2p'(s)}{p(s)^{3/2}} - \frac{4\lambda\sqrt{\eps(s)}}{(\alpha(s)+\beta\lambda)^{3/2}}\right)^2$. Focusing on the first exponential term in \eqref{eq::formofx0}, we deduce from \eqref{eq::sqrtr} that for all $t\geq 0$,
\begin{align*}%\label{eq::Aexpterm}
	\begin{split}
		&\exp\left(\int_0^t -\frac{p(s)}{2} +\sqrt{r(s)}\diff s\right)
		\\&= \exp\left(\int_0^t \frac{\alpha'(s)/2}{\alpha(s)+\beta\lambda} -\frac{\eps'(s)}{2\eps(s)} -\frac{\lambda}{\alpha(s)+\beta\lambda} - \frac{1}{16}h(t) + o(\eps(s))\diff s\right)
		\\&=  \frac{\sqrt{\alpha(t)+\beta\lambda})}{\sqrt{\alpha_0+\beta\lambda}} \frac{\sqrt{\eps_0}}{\sqrt{\eps(t)}} \exp\left(
		\int_0^t \frac{-\lambda}{\alpha(s)+\beta\lambda} -
		\frac{1}{16}h(t) + o(\eps(s))\diff s\right)
		\\&=  \frac{\sqrt{\alpha(t)+\beta\lambda})}{\sqrt{\alpha_0+\beta\lambda}} \frac{\sqrt{\eps_0}}{\sqrt{\eps(t)}} \exp\left(
		\int_0^t \frac{-\lambda}{\alpha(s)+\beta\lambda} -
		\frac{\lambda^2\eps(s)}{(\alpha(s)+\beta\lambda)^{3}} + o(\eps(s))\diff s\right),
	\end{split}
\end{align*}

\begin{theorem}\label{thm::MainResAsymptotic}
		Let $x$ be the solution of \eqref{eq::QuadeDINAVD}, given in \eqref{eq::formofx}, and $x_{LM}$ and $x_N$ whose closed forms are stated in \eqref{eq::closeformLMN}. Under Assumptions~\ref{ass:smooth} and~\ref{ass:subexp}, there exists $C>0$ such that the following asymptotic equivalences hold:
		\begin{align}\label{eq::equivx}
			\begin{split}
				x(t) &\sim_{+\infty}
				x_{LM}(t)C\exp\left(\int_0^t - \frac{\lambda^2\eps(s)}{(\alpha(s)+\beta\lambda)^{3}}+o(\eps(s))\diff s\right),\quad \text{and}
				\\x(t)&\sim_{+\infty}
				x_{N}(t)C\exp\left(\int_0^t \frac{\alpha(s)}{\beta(\alpha(s)+\beta\lambda)}- \frac{\lambda^2\eps(s)}{(\alpha(s)+\beta\lambda)^{3}}+o(\eps(s))\diff s\right).
			\end{split}
		\end{align}
		As a consequence, the convergence of $x$ to $x^\star$ is:
		\begin{enumerate}[label=(\roman*)]
			\item \emph{Faster} than that of $x_{LM}$
			if $\eps$ is non-integrable and as fast otherwise.
			\item Slower than that of $x_{N}$ if $\alpha$ is non-integrable and as fast if $\alpha$ is integrable, in the case where $\forall t\geq 0$, $\alpha(t)>\eps(t)$.
			\item \emph{Faster} than that of $x_{N}$ if $\eps$ is non-integrable and as fast if $\eps$ is integrable, in the case where $\forall t\geq 0$, $\alpha(t)< \eps(t)$.
		\end{enumerate}
	\end{theorem}

Let us now focus on the first term in \eqref{eq::formofx}. Observe that
$\exp\left(\int_0^t -\frac{\lambda}{\alpha(s)+\beta\lambda}\diff s\right)$ is exactly the decay of $x_{LM}$ in \eqref{eq::closeformLMN}. Thus, we have proved that there exists $C>0$, such that the following asymptotic equivalence holds,
\begin{multline*}%\label{eq::equivA}
	A\frac{1+\delta_1(t)}{r(t)^{1/4}}\frac{\sqrt{\alpha(t)+\beta\lambda}}{\sqrt{\eps(t)}}\exp\left(\int_0^t -\frac{\lambda}{\alpha(s)+\beta\lambda} - \frac{\lambda^2\eps(s)}{(\alpha(s)+\beta\lambda)^{3}}+o(\eps(s))\diff s\right)
	\\ \sim_{+\infty}
	x_{LM}(t)C\exp\left(\int_0^t - \frac{\lambda^2\eps(s)}{(\alpha(s)+\beta\lambda)^{3}}+o(\eps(s))\diff s\right),
\end{multline*}

which proves the first part of \eqref{eq::equivx}. The second equivalence in \eqref{eq::equivx} is obtained using the following identity,
\begin{equation}\label{eq::rewritteLM}
	\int_0^t -\frac{\lambda}{\alpha(s)+\beta\lambda}\diff s = \int_0^t -\frac{1}{\beta} + \frac{\alpha(s)}{\beta(\alpha(s)+\beta\lambda)}\diff s = -\frac{t}{\beta} + \int_0^t  \frac{\alpha(s)}{\beta(\alpha(s)+\beta\lambda)}\diff s
\end{equation}
and $e^{-t/\beta}$ is precisely the rate at which $x_N$ decreases. So \eqref{eq::equivx} holds.

This paper emphasizes the relation between \eqref{eq::VMDINAVD} and special cases.
Indeed, taking $\eps=\alpha=0$, one obtains\footnote{\ref{eq::CN} is usually considered with $\beta=1$, we put $\beta$ in the system to ease the discussions below.} the Continuous Newton (CN) method \citep{gavurin1958nonlinear}
\begin{equation}\tag{CN}\label{eq::CN}
	\beta \Hf(x_N(t))\dot{x}_N(t)+\gf(x_N(t))=0, \quad t\geq 0,
\end{equation}
known notably for being invariant to affine transformations and yielding fast vanishing of the gradient (see Section~\ref{sec::Control}).
In fact, this observation shows that \eqref{eq::VMDINAVD} is a singular perturbation of \eqref{eq::CN}, which also justifies the terminology ``Newton-like''  in DIN.

When $\alpha\neq 0$ but $\eps=0$, we recover the Levenberg--Marquardt (LM) method,
\begin{equation}\tag{LM}\label{eq::LM}
	\alpha(t) \dot x_{LM}(t) + \beta \Hf(x_{LM}(t))\dot{x}_{LM}(t)+\gf(x_{LM}(t))=0, \quad t\geq 0,
\end{equation}
also known as regularized Newton method since it stabilizes \eqref{eq::CN}.
In the rest of the paper, the solutions of \eqref{eq::CN} and \eqref{eq::LM} will always be denoted by $x_N$ and $x_{LM}$ respectively. Since the introduction of DIN, it is known (see \cite{alvarez2002second}) that for $\alpha=0$, $\beta=1$, and $\eps$ constant and small, \eqref{eq::VMDINAVD} is a ``perturbed'' Newton method since the distance between the solutions of \eqref{eq::VMDINAVD} and \eqref{eq::CN}  is at most proportional to $\sqrt{\eps}$ at all times.

We always assume the following on the system \eqref{eq::VMDINAVD} and the functions $f,\eps,\alpha$ defined in the introduction.
	\begin{assumption}\label{ass:general}
		\textbullet\ $f: \R^n \to \R$ is convex, twice continuously differentiable, coercive, and strongly convex on bounded subsets of $\R^n$.

	\textbullet\ $\alpha: \R_+ \to \R$ is non-increasing, non-negative and differentiable. $\eps: \R_+ \to \R$ is non-increasing, positive, and twice differentiable with bounded second derivative.
	We fix initial values: $\eps(0)=\eps_0>0$, $\eps'(0)=\eps'_0\leq0$ and $\alpha(0)=\alpha_0\geq 0$.
\end{assumption}

\section{Approximate Solutions and Asymptotic Analysis on Quadratics}\label{sec::Quads}
In addition to Assumption~\ref{ass:general}, we consider the case where $f$ is a strongly convex quadratic function in order to study the asymptotic behavior of \eqref{eq::VMDINAVD} w.r.t.\ \eqref{eq::CN} and \eqref{eq::LM}. Quadratic functions are the prototypical example of strongly convex functions. In particular, any strongly convex function can be locally approximated by a quadratic one around its minimizer, making the latter a good model for understanding the local behavior of dynamics.
In this section, $f$ is quadratic: $f(y)=\frac{1}{2}\Vert Ay-b\Vert_2^2$ for all $y\in \R^n$, where $A\in\R^{n\times n}$ is symmetric positive definite and $b\in\R^n$. Without loss of generality, we take $b=0$, so that the unique minimum is $x^\star=0$.
\subsection{Setting: the Special Case of Quadratic Functions}
Quadratic functions are particularly interesting in our setting since DIN-like ODEs take a simpler form (as observed in \cite{attouch2020first,shi2021understanding}). Indeed, $\forall y\in\R^n$, $\gf(y) = A^TAy$ and $\Hf(y)=A^T A$. Since $\Hf(y)$ is independent of $y$ we can rewrite \eqref{eq::VMDINAVD} in an eigenspace\footnote{This can be generalized to the case where $A^TA$ is only semi-definite by considering orthogonal projections on an eigenspace spanned by the positive eigenvalues of $A^TA$.} of  $A^TA$. That is, we can study the ODE coordinate-wise by looking at one-dimensional problems of the form

\begin{equation}\label{eq::QuadeDINAVD}\tag{Q1-VM-DIN-AVD}
	\eps(t)\ddx(t)+(\alpha(t)+\beta\lambda)\dx(t)+\lambda x(t)=0, \quad t\geq 0.
\end{equation}
Here (and throughout what follows) $\lambda>0$ denotes any eigenvalue of $A^TA$ and $x\colon\R_+\to\R$ now denotes the corresponding  coordinate (function) of the solution of \eqref{eq::VMDINAVD} in an eigenspace of $A^TA$. The dynamics \eqref{eq::QuadeDINAVD} is a \emph{linear} second-order ODE in $x$ with non-constant coefficients. Similarly, \eqref{eq::LM} can be rewritten coordinate-wise as

\begin{equation}\label{eq::quadLM}\tag{Q1-LM}
	(\alpha(t)+\beta\lambda)\dx_{LM}(t)+\lambda x_{LM}(t)=0, \quad t\geq 0,
\end{equation}
where $\xlm\colon\R_+\to\R$, and \eqref{eq::CN} becomes
\begin{equation}\label{eq::quadCN}\tag{Q1-CN}
	\beta\dx_N(t)+ x_N(t)=0, \quad t\geq 0,
\end{equation}
where again, $x_N\colon\R_+\to\R$ is one-dimensional.

Observe in particular that \eqref{eq::CN} and \eqref{eq::LM} are now first-order \emph{linear} ODEs, whose solutions have closed forms: $\forall t\geq 0$,
\begin{equation}\label{eq::closeformLMN}
	x_N(t) = x_0e^{-\frac{t}{\beta}}
	\quad \text{and}\quad
	x_{LM}(t) = x_0\exp\left(-\int_0^t \frac{\lambda}{\alpha(s)+\beta\lambda}\diff s \right).
\end{equation}

\begin{theorem}[\cite{olver1997asymptotics}]\label{thm::olver}
	Let $r\colon \R_{+}\to \R$ be a real, positive, twice continuously differentiable function, and define $\varphi(t) = \frac{4r(t)r''(t)-5r'(t)^2}{16r(t)^{5/2}}$ for all $t\geq 0$. Then for any $T>0$, the differential equation,
	\begin{equation}\label{eq::GenericODEthm}
		\ddot{z}(t)-r(t)z(t)=0,\quad t\in [0,T],
	\end{equation}
	has two real and twice continuously differentiable solutions defined $\forall t\in[0,T]$ by,
	\begin{equation*}
		z_1(t) = \frac{1+\delta_1(t)}{r(t)^{1/4}}\exp\left(\int_0^t \sqrt{r(s)}\diff s\right) \ \ \text{and} \ \,
		z_2(t) = \frac{1+\delta_2(t)}{r(t)^{1/4}}\exp\left(-\int_0^t \sqrt{r(s)}\diff s\right),
	\end{equation*}
	where $\displaystyle\vert\delta_1(t)\vert\leq \exp\left(\frac{1}{2} \int_0^t \vert \varphi(s)\vert\diff s\right)-1$ and $\displaystyle\vert\delta_2(t)\vert\leq \exp\left(-\frac{1}{2} \int_t^{T} \vert \varphi(s)\vert\diff s\right)-1$.
	If in addition $\displaystyle\int_0^{+\infty} \vert\varphi(s)\vert\diff s <+\infty$, then the results above also hold for $T=+\infty$.
\end{theorem}

We now proceed to make use of the LG method for approximating the solutions of \eqref{eq::QuadeDINAVD}. The reader only interested in the result can jump directly to the  Section~\ref{sec::mainasymptoticres}. We first make the following assumption.
\begin{assumption}\label{ass:smooth}
	The functions $\alpha$ and $\eps$ are three times continuously differentiable, and $\eps_0$ is such that $\forall t\geq 0$, $\eps_0<\frac{(\beta\lambda)^2}{2\vert\alpha'(t)\vert+4\lambda}$.
\end{assumption}

\begin{assumption}\label{ass:subexp}
	The functions $\eps$ and $\alpha$ have first, second and third-order derivatives that are integrable on $[0,+\infty[$. In addition, $\lim\limits_{t\to\infty}{\eps(t)}=0$ and $\eps'(t)^2/\eps(t)$ is integrable on $[0,+\infty[$.
\end{assumption}

\begin{lemma}\label{lem::canonForm}
		Suppose that Assumption~\ref{ass:smooth} holds, and let $x$ be the solution of \ref{eq::QuadeDINAVD}. For all $t\geq 0$, define
		\begin{equation}\label{eq::pr}
			p(t) = \frac{\alpha(t)+\beta\lambda}{\eps(t)} \quad \text{and}  \quad r(t) = \frac{p(t)^2}{4} + \frac{p'(t)}{2} - \frac{\lambda}{\eps(t)}.
		\end{equation}
		Then, $p$ and $r$ are twice continuously differentiable, $r$ is positive and the function $y$ defined for all $t\geq 0$ by $y(t) = x(t)\exp\left(\int_0^t \frac{p(s)}{2}\diff s\right)$ is a solution to
		\begin{equation}\label{eq::ODErewritten}
			\ddot y(t) - r(t)y(t) = 0,\quad t\geq 0,%\\
		\end{equation}
		with initial condition $(y(0),\dot{y}(0) )= (x_0,\dx_0 + \frac{p(0)}{2}x_0)$.
	\end{lemma}

Suppose that Assumption~\ref{ass:smooth} holds, and let $x$ be the solution of \ref{eq::QuadeDINAVD}. For all $t\geq 0$, define
\begin{equation}\label{eq::pr}
	p(t) = \frac{\alpha(t)+\beta\lambda}{\eps(t)} \quad \text{and}  \quad r(t) = \frac{p(t)^2}{4} + \frac{p'(t)}{2} - \frac{\lambda}{\eps(t)}.
\end{equation}

\begin{proof}
		We first check that for all $t\geq 0$, $r(t)$ is positive. Let $t>0$,
		\begin{equation}\label{eq::rpositive}
			r(t)> 0 \iff \frac{(\alpha(t)+\beta\lambda)^2}{4\eps(t)^2} + \frac{\alpha'(t)}{2\eps(t)} -  \frac{(\alpha(t)+\beta\lambda)\eps'(t)}{\eps(t)^2} - \frac{\lambda}{\eps(t)} >0.
		\end{equation}
		Since $\eps'(t)\leq 0$ and $\alpha'(t)\leq 0$, one can check that a sufficient condition for \eqref{eq::rpositive} to hold is,
		\begin{equation*}
			r(t)> 0 \impliedby \frac{(\alpha(t)+\beta\lambda)^2}{4} > \left(\frac{\vert\alpha'(t)\vert}{2}+\lambda\right)\eps(t) \impliedby \frac{(\beta\lambda)^2}{2\vert\alpha'(t)\vert+4\lambda}>\eps_0.
		\end{equation*}
		So under Assumption~\ref{ass:smooth}, for all $t\geq 0$, $r(t)>0$. We then check that $y$ is indeed solution to \eqref{eq::ODErewritten}. Let $t>0$,
		\begin{equation*}
			\dot{y}(t) = \frac{p(t)}{2}x(t)\exp\left(\int_0^t \frac{p(s)}{2}\diff s\right) + \dx(t)\exp\left(\int_0^t \frac{p(s)}{2}\diff s\right),\quad \text{and,}
		\end{equation*}
		\begin{equation*}
			\ddot{y}(t) = \exp\left(\int_0^t \frac{p(s)}{2}\diff s\right)\left[\left(\frac{p(t)^2}{4}+\frac{p'(t)}{2}\right)x(t) + p(t)\dx(t) + \ddx(t)\right].
		\end{equation*}
		Since $x$ solves \eqref{eq::QuadeDINAVD}, it holds that $\ddx(t) = -p(t)\dx(t) - \frac{\lambda}{\eps(t)}x(t)$, so,
		\begin{multline*}
			\ddot{y}(t) = \exp\left(\int_0^t \frac{p(s)}{2}\diff s\right)\left(\frac{p(t)^2}{4}+\frac{p'(t)}{2}- \frac{\lambda}{\eps(t)}\right)x(t) \\= \left(\frac{p(t)^2}{4}+\frac{p'(t)}{2}- \frac{\lambda}{\eps(t)}\right)y(t)
			= r(t)y(t).
		\end{multline*}
	\end{proof}

\begin{proof}
		We first check that for all $t\geq 0$, $r(t)$ is positive. Let $t>0$,
		\begin{equation}\label{eq::rpositive}
			r(t)> 0 \iff \frac{(\alpha(t)+\beta\lambda)^2}{4\eps(t)^2} + \frac{\alpha'(t)}{2\eps(t)} -  \frac{(\alpha(t)+\beta\lambda)\eps'(t)}{\eps(t)^2} - \frac{\lambda}{\eps(t)} >0.
		\end{equation}
		Since $\eps'(t)\leq 0$ and $\alpha'(t)\leq 0$, one can check that a sufficient condition for \eqref{eq::rpositive} to hold is,
		\begin{equation*}
			r(t)> 0 \impliedby \frac{(\alpha(t)+\beta\lambda)^2}{4} > \left(\frac{\vert\alpha'(t)\vert}{2}+\lambda\right)\eps(t) \impliedby \frac{(\beta\lambda)^2}{2\vert\alpha'(t)\vert+4\lambda}>\eps_0.
		\end{equation*}
		So under Assumption~\ref{ass:smooth}, for all $t\geq 0$, $r(t)>0$. We then check that $y$ is indeed solution to \eqref{eq::ODErewritten}. Let $t>0$,

	\begin{equation*}
		\dot{y}(t) = \frac{p(t)}{2}x(t)\exp\left(\int_0^t \frac{p(s)}{2}\diff s\right) + \dx(t)\exp\left(\int_0^t \frac{p(s)}{2}\diff s\right),\quad \text{and,}
	\end{equation*}
	\begin{equation*}
		\ddot{y}(t) = \exp\left(\int_0^t \frac{p(s)}{2}\diff s\right)\left[\left(\frac{p(t)^2}{4}+\frac{p'(t)}{2}\right)x(t) + p(t)\dx(t) + \ddx(t)\right].
	\end{equation*}
	Since $x$ solves \eqref{eq::QuadeDINAVD}, it holds that $\ddx(t) = -p(t)\dx(t) - \frac{\lambda}{\eps(t)}x(t)$, so,
	\begin{multline*}
		\ddot{y}(t) = \exp\left(\int_0^t \frac{p(s)}{2}\diff s\right)\left(\frac{p(t)^2}{4}+\frac{p'(t)}{2}- \frac{\lambda}{\eps(t)}\right)x(t) \\= \left(\frac{p(t)^2}{4}+\frac{p'(t)}{2}- \frac{\lambda}{\eps(t)}\right)y(t)
		= r(t)y(t).
	\end{multline*}
\end{proof}

\begin{lemma}\label{lem::phiintegrable}
		Under Assumption~\ref{ass:smooth} and~\ref{ass:subexp}, $\int_0^{+\infty} \vert \varphi(s)\vert\diff s<+\infty$.
	\end{lemma}

\begin{proof}
		We suppose that Assumptions~\ref{ass:smooth} and~\ref{ass:subexp} hold. As stated in Remark~\ref{rem::olver}, since $\varphi$ is continuous, we only need to check its integrability when $t$ tends to $+\infty$. Let $t>0$, we first establish some useful identities, we omit the dependence on $t$ for the sake of readability.
		\begin{align*}%\label{eq::pprime}
			p' = \frac{\alpha'\eps-(\alpha+\beta\lambda)\eps'}{\eps^2},
			\quad \text{and}\quad
			p'' = \frac{\alpha''\eps^2-2\alpha'\eps'\eps-(\alpha+\beta\lambda)\eps''\eps + 2(\alpha+\beta\lambda)(\eps')^2}{\eps^3}.
		\end{align*}
		Then,
		\begin{align}\label{eq::factorR}
			\begin{split}
				r  &= \frac{p^2}{4}\left(1+ \frac{2p'}{p^2} - \frac{4\lambda}{\eps p^2}\right) = \frac{(\alpha+\beta\lambda)^2}{4\eps^2}\left(1+\frac{2p' \eps ^2}{(\alpha +\beta\lambda)^2} - \frac{4\lambda\eps }{(\alpha +\beta\lambda)^2}\right)
				\\
				&=\frac{(\alpha +\beta\lambda)^2}{4\eps ^2}\left(1+\frac{2\alpha' \eps }{(\alpha +\beta\lambda)^2} - \frac{2\eps' }{(\alpha +\beta\lambda)} - \frac{4\lambda\eps }{(\alpha +\beta\lambda)^2}\right).
			\end{split}
		\end{align}
		An important consequence of Assumption~\ref{ass:subexp} is that $\vert\eps'(t)\vert = o(\eps(t))$, $\vert\eps''(t)\vert = o(\eps'(t))$ (and the same holds for $\alpha$ w.r.t.\ to its derivatives). Therefore, we deduce from \eqref{eq::factorR} that
		\begin{equation*}
			r(t)\sim_{+\infty}  \frac{(\alpha(t)+\beta\lambda)^2}{4\eps(t)^2},
		\end{equation*}
		and we note that $1/r$ decays at the same speed as $\eps^2$, which will be useful later. In order to study $\varphi$, we now differentiate $r$,
		\begin{align}\label{eq::rprime}
			\begin{split}
				r' &= \frac{p'p}{2}\left(1+ \frac{2p'}{p^2} - \frac{4\lambda}{\eps p^2}\right) + \frac{1}{4}\left( 2p'' - \frac{4(p')^2}{p} + \frac{8\lambda p'}{\eps p}+ \frac{4\lambda\eps'}{\eps^2} \right)
				\\&= \frac{2p'}{p}r + \frac{1}{4}\left( 2p'' - \frac{4(p')^2}{p} +\frac{8\lambda p'}{\eps p} + \frac{4\lambda\eps'}{\eps^2}  \right),\quad \text{and,}
			\end{split}
		\end{align}

		\begin{multline}\label{eq::rsec}
			r'' = 2\frac{p''p-(p')^2}{p^2}r  + \frac{2p'}{p}r'
			\\
			+ \frac{1}{4}\left( 2p''' + 4\frac{(p')^3-2p''p'p}{p^2}+8 \lambda\frac{p''p\eps - (p')^2\eps - p'p\eps'}{\eps^2 p^2} + \frac{4\lambda\eps''}{\eps^2} - \frac{8\lambda(\eps')^2}{\eps^3}  \right).
		\end{multline}
		Then, to justify that $\varphi$ is integrable, we prove that $\frac{r''}{r^{3/2}}$ and $\frac{(r')^2}{r^{5/2}}$ are integrable. Since we know that $1/r$ decays at the same speed as $\eps^2$, we can equivalently show that $\eps^3r''$ and $\eps^5(r')^2$ are integrable.
		To this aim we fully expand all the terms in \eqref{eq::rprime} and \eqref{eq::rsec}.
		We first deal with \eqref{eq::rprime}, it holds that:
		\begin{align*}
			r'^2&\eps^{5} =
			\left[- \frac{ (\alpha+\beta\lambda)^{2} \left(- \frac{4 \lambda \eps }{ (\alpha+\beta\lambda)^{2}} + 1 + \frac{\left(- {2  (\alpha+\beta\lambda) \eps' } + {2 \alpha'\eps }\right) }{ (\alpha+\beta\lambda)^{2}}\right) \eps' }{2 \sqrt{\eps}}\right.
			\\ &\left.
			+ \frac{ (\alpha+\beta\lambda)^{2}\sqrt{\eps}}{4} \left(- \frac{4 \lambda \eps' }{ (\alpha+\beta\lambda)^{2}} + \frac{8 \lambda \alpha'  \eps }{ (\alpha+\beta\lambda)^{3}} + \frac{2 \left(- \frac{2  (\alpha+\beta\lambda) \eps' }{\eps } + {2 \alpha'\eps }\right) \eps'   }{ (\alpha+\beta\lambda)^{2}}
			\right.\right.
			\\&\left.\left.
			+ \frac{\left(\frac{4  (\alpha+\beta\lambda) \eps'^{2} }{\eps } - {2  (\alpha+\beta\lambda) \eps'' } - {4 \alpha'  \eps' } + {2 \alpha''\eps }\right) }{ (\alpha+\beta\lambda)^{2}} - \frac{2 \left(-{2  (\alpha+\beta\lambda) \eps' } + {2 \alpha'\eps }\right) \alpha'   }{ (\alpha+\beta\lambda)^{3}}\right)
			\right.\\
			&\left. + \frac{ (\alpha+\beta\lambda)}{2} { \left(- \frac{4 \lambda \eps }{ (\alpha+\beta\lambda)^{2}} + 1 + \frac{\left(- {2  (\alpha+\beta\lambda) \eps' } + {2 \alpha'\eps }\right) }{ (\alpha+\beta\lambda)^{2}}\right)} \alpha' \sqrt{\eps}
			\phantom{\frac{\frac{\beta}{\beta}}{\beta}}
			\hspace{-1.7cm}\phantom{\frac{\left( \frac{\frac{a'}{a'}}{a'}\right)}{a^2}{\sqrt{.}}
			}\right]^{2}.
		\end{align*}
		The computations for $\eps^2r''$ are omitted since they are longer but very similar.

